    SELECT id INTO pitchdeck_id FROM public.objective_packs WHERE title = 'Pitch Deck Builder' LIMIT 1;
    SELECT id INTO network_id FROM public.objective_packs WHERE title = 'Network Effects & Cold Start Strategy' LIMIT 1;
    SELECT id INTO series_a_id FROM public.objective_packs WHERE title = 'Series A Readiness Checklist' LIMIT 1;
    SELECT id INTO equity_id FROM public.objective_packs WHERE title = 'Equity & Option Grant Planning' LIMIT 1;

